        "Kada se govori o mjestu, situaciji ili osobi, sicher = sigurno (ein sicherer Ort = sigurno mjesto).",
        "Kao potvrda ili uvjeravanje u rečenici, sicher = svakako/naravno (Das ist sicher wahr. = Svakako je istina.).",
